{"command": "cd /workspace && cat > /tmp/t/an3.py <<'EOF'
import sys,collections,re
lines=[l for l in open(sys.argv[1]) if l.startswith('x ')]
comps=[]
for line in lines:
    m=re.match(r'x\s+(\d+)-(\d+)\s+y\s+(\d+)-\s*(\d+)\s+w=(\d+) h=(\d+) n=(\d+)',line)
    if not m: continue
    x0,x1,y0,y1,w,h,n=map(int,m.groups())
    comps.append((x0,x1,y0,y1,w,h,n))
comps.sort(key=lambda c:(c[2],c[0]))
# group by vertical overlap
groups=[]
for c in comps:
    placed=False
    for g in groups:
        if not (c[3] < g[0][2]-2 or c[2] > g[-1][3]+2):
            g.append(c); placed=True; break
    if not placed: groups.append([c])
for g in groups:
    g.sort(key=lambda c:c[0])
    print('rows %3d-%3d n=%2d lefts=%s bots=%s widths=%s'%(g[0][2],g[-1][3],len(g),[c[0] for c in g[:16]],sorted(set(c[3] for c in g)),[c[4] for c in g[:16]]))
EOF
