{"command": "cd /workspace && cat > /tmp/t/fit.py <<'EOF'
import sys, math, random
sys.path.insert(0,'/tmp/t')
from lib import load

def orient(poly):
    s=0.0
    n=len(poly)
    for i in range(n):
        x1,y1=poly[i]; x2,y2=poly[(i+1)%n]
        s+=x1*y2-x2*y1
    return 1 if s>0 else -1

def inside(poly,px_,py):
    o=orient(poly)
    for i in range(len(poly)):
        x1,y1=poly[i]; x2,y2=poly[(i+1)%len(poly)]
        cr=(x2-x1)*(py-y1)-(y2-y1)*(px_-x1)
        if cr*o < -1e-9: return False
    return True

def cov_quad(pts, x, y, sub=6):
    n=0
    for i in range(sub):
        for j in range(sub):
            if inside(pts,x+(i+0.5)/sub,y+(j+0.5)/sub): n+=1
    return n/(sub*sub)

def model(params):
    x0,y0,x1,y1,W=params
    dx,dy=x1-x0,y1-y0
    L=math.hypot(dx,dy)
    nx,ny=-dy/L,dx/L
    qx,qy=nx*W/2,ny*W/2
    return [(x0+qx,y0+qy),(x1+qx,y1+qy),(x1-qx,y1-qy),(x0-qx,y0-qy)]

def fit(target_png, X0,X1,Y0,Y1, p0, steps=(2.0,2.0,2.0,2.0,1.0), tol=0.05):
    w,h,px=load(target_png)
    obs=[[ (254-px[y][x][0])/254.0 for x in range(X0,X1)] for y in range(Y0,Y1)]
    def err(params, sub=4):
        pts=model(params)
        e=0.0
        for yy in range(Y0,Y1):
            for xx in range(X0,X1):
                e+=(cov_quad(pts,xx,yy,sub)-obs[yy-Y0][xx-X0])**2
        return e
    cur=list(p0); c=err(cur)
    step=list(steps)
    while True:
        improved=False
        for i in range(len(cur)):
            for s in (step[i],-step[i]):
                trial=list(cur); trial[i]+=s
                e=err(trial)
                if e<c: cur=trial; c=e; improved=True
        if not improved:
            step=[s/2 for s in step]
            if max(step)<tol: break
    return cur,c

if __name__=='__main__':
    cur,c=fit('/tmp/t/a5_4.png',140,180,112,172,[159.0,117.0,146.0,166.0,6.5])
    print('best',[round(v,3) for v in cur],'err',c)
    pts=model(cur)
    for p in pts: print('corner',round(p[0],3),round(p[1],3))
    for y in [118,125,132,140,150,160]:
        print('y',y,'model',' '.join('%3d'%round(254*cov_quad(pts,x,y,6)) for x in range(146,162)))
        print('y',y,'obs  ',' '.join('%3d'%px[y][x][0] for x in range(146,162)))
EOF
