def to_curves(contours):
    segs=[]
    for pts in contours:
        n=len(pts)
        if all(not p[2] for p in pts): continue
        idx=0
        for i,p in enumerate(pts):
            if p[2]: idx=i; break
        pts=pts[idx:]+pts[:idx]
        segs_c=[]
        i=0
        while i<n:
            p0=pts[i%n]
            j=(i+1)%n
            p1=pts[j]
            if p1[2]:
                segs_c.append(('L',p0[0],p0[1],p1[0],p1[1]))
                i=j
            else:
                k=(j+1)%n
                p2=pts[k]
                segs_c.append(('Q',p0[0],p0[1],p1[0],p1[1],p2[0],p2[1]))
                i=k
        segs.append(segs_c)
    return segs

def flatten(curves, steps=16):
    polys=[]
    for c in curves:
        pts=[]
        prev=None
        for s in c:
            if s[0]=='L':
                p=(s[1],s[2]); q=(s[3],s[4])
                if prev is None: pts.append(p)
                elif prev!=p: pts.append(p)
                pts.append(q); prev=q
            else:
                p0=(s[1],s[2]); p1=(s[3],s[4]); p2=(s[5],s[6])
                if prev is None: pts.append(p0)
                elif prev!=p0: pts.append(p0)
                for t in range(1,steps+1):
                    u=t/steps
                    x=(1-u)**2*p0[0]+2*(1-u)*u*p1[0]+u*u*p2[0]
                    y=(1-u)**2*p0[1]+2*(1-u)*u*p1[1]+u*u*p2[1]
                    pts.append((x,y))
                prev=(p2)
        polys.append(pts)
    return polys

def rasterize_lines(polys, w, h, sub=8):
    cov=[[0.0]*w for _ in range(h)]
    dy=1.0/sub
    allrows=[]
    for r in range(h*sub):
        sy=(r+0.5)*dy
        ev=[]
        for poly in polys:
            n=len(poly)
            for k in range(n):
                x1,y1=poly[k]; x2,y2=poly[(k+1)%n]
                if y1==y2: continue
                if (y1<=sy<y2) or (y2<=sy<y1):
                    t=(sy-y1)/(y2-y1)
                    xx=x1+t*(x2-x1)
                    ev.append(xx)
        ev.sort()
        intervals=[(ev[i],ev[i+1]) for i in range(0,len(ev)-1,2)]
        allrows.append(intervals)
    for py in range(h):
        for px_ in range(w):
            tot=0.0
            for r in range(sub):
                for (a,b) in allrows[py*sub+r]:
                    lo=max(a,px_); hi=min(b,px_+1)
                    if hi>lo: tot += (hi-lo)*dy
            cov[py][px_]=tot
    return cov
