        ny = dx / L * hw
        left.append(((x1 + nx, y1 + ny), (x2 + nx, y2 + ny)))
        right.append(((x1 - nx, y1 - ny), (x2 - nx, y2 - ny)))
    if not left:
        return []
    polys = []
    # left chain
    lpts = [left[0][0]]
    for i in range(len(left)):
        lpts.append(left[i][1])
        if i + 1 < len(left):
            lpts.append(left[i + 1][0])
    rpts = [right[-1][1]]
    for i in range(len(right) - 1, -1, -1):
        rpts.append(right[i][0])
        if i - 1 >= 0:
            rpts.append(right[i - 1][1])
    poly = lpts + rpts
    if not closed:
        # add caps
        if caps == 'butt':
            pass
        elif caps == 'round':
            # approximate with arcs
            pass
        elif caps == 'square':
            pass
    polys.append(poly)
    return polys
