"""Low-level rasterization: exact-area coverage of polygons and strokes."""
import math

# ---------------------------------------------------------------- helpers
def _fmt(v):
    return v

def poly_area_signed(pts):
    a = 0.0
    n = len(pts)
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i + 1) % n]
        a += x1 * y2 - x2 * y1
    return a / 2.0


class Canvas:
    """Coverage accumulator with colour compositing."""

    def __init__(self, width, height, background=(0xFE, 0xFE, 0xFE), alpha=255):
        self.width = width
        self.height = height
        self.px = [[list(background) + [255] for _ in range(width)] for _ in range(height)]

    def clear_border(self, color):
        """Fill the outer 3-pixel frame with color (opaque)."""
        for y in range(min(3, self.height)):
            for x in range(self.width):
                self.px[y][x] = list(color) + [255]
                self.px[self.height - 1 - y][x] = list(color) + [255]
        for x in range(min(3, self.width)):
            for y in range(self.height):
                self.px[y][x] = list(color) + [255]
                self.px[y][self.width - 1 - x] = list(color) + [255]

    # ---------------------------------------------------------- paths
    def fill_paths(self, polys, color, alpha=1.0):
        """Fill a set of polygons (nonzero winding) with exact area coverage."""
        if not polys:
            return
        cov = self._coverage(polys)
        self._composite(cov, color, alpha)

    def _coverage(self, polys):
        w = self.width
        h = self.height
        cov = [[0.0] * w for _ in range(h)]
        for pts in polys:
            n = len(pts)
            if n < 3:
                continue
            ymin = max(0, int(math.floor(min(p[1] for p in pts))))
            ymax = min(h - 1, int(math.ceil(max(p[1] for p in pts))))
            for y in range(ymin, ymax + 1):
                y0 = y
                y1 = y + 1.0
                self._scanline(pts, y0, y1, cov, w, y)
        return cov

    @staticmethod
    def _scanline(pts, y0, y1, cov, w, yi):
        # accumulate signed trapezoid area contributions clipped to the row
        n = len(pts)
        events = []  # (xc at y0, xc at y1, sign)
        for i in range(n):
            ax, ay = pts[i]
            bx, by = pts[(i + 1) % n]
            if ay == by:
                continue
            if ay > by:
                ax, ay, bx, by = bx, by, ax, ay
                sign = -1
            else:
                sign = 1
            if by <= y0 or ay >= y1:
                continue
            # clip to [y0, y1]
            ay0 = max(ay, y0)
            by0 = min(by, y1)
            xa = ax + (bx - ax) * (ay0 - ay) / (by - ay)
            xb = ax + (bx - ax) * (by0 - ay) / (by - ay)
            events.append((xa, xb, sign, ay0, by0))
        if not events:
            return
        # for each pixel column, integrate the coverage of this polygon over the row
        # we need to combine the events by x position
        xs = sorted(set([e[0] for e in events] + [e[1] for e in events]))
        for yi_row in range(0):
            pass
        row = cov[yi]
        for j in range(len(xs) - 1):
            a, b = xs[j], xs[j + 1]
            if b < 0 or a > w:
                continue
            # integrate the winding over y in [y0,y1] and x in [a,b]
            for xlo in range(max(0, int(math.floor(a))), min(w, int(math.ceil(b)))):
                xl = max(a, xlo)
                xr = min(b, xlo + 1.0)
                if xr <= xl:
                    continue
                tot = 0.0
                for (xa, xb, sign, ay0, by0) in events:
                    xla = max(xl, xa)
                    xrb = min(xr, xb)
                    if xrb <= xla:
                        continue
                    # trapezoid: sign * integral dy of the x-extent
                    tot += sign * (xrb - xla) * (by0 - ay0)
                if tot:
                    f = abs(tot)
                    if f > 1.0:
                        f = 1.0
                    row[xlo] = min(1.0, row[xlo] + f)

    def _composite(self, cov, color, alpha=1.0):
        for y in range(self.height):
            row = cov[y]
            prow = self.px[y]
            for x in range(self.width):
                c = row[x]
                if c <= 0:
                    continue
                a = c * alpha
                if a > 1.0:
                    a = 1.0
                p = prow[x]
                for k in range(3):
                    p[k] = int(round(color[k] * a + p[k] * (1 - a)))
                p[3] = max(p[3], int(round(255 * a)))

    # ---------------------------------------------------------- strokes
    def stroke_path(self, polys, color, width=1.0, caps='butt', joins='round', dash=None):
        for pts in polys:
            out = _stroke_polygon(pts, width, caps, joins)
            self.fill_paths(out, color)


def _stroke_polygon(pts, width, caps, joins):
    """Return list of polygons forming the stroke outline of a closed/open polyline."""
    n = len(pts)
    if n < 2:
        return []
    closed = False
    if n > 2 and abs(pts[0][0] - pts[-1][0]) < 1e-9 and abs(pts[0][1] - pts[-1][1]) < 1e-9:
        closed = True
    hw = width / 2.0
    left = []
    right = []
    for i in range(n - 1):
        x1, y1 = pts[i]
        x2, y2 = pts[i + 1]
        dx = x2 - x1
        dy = y2 - y1
        L = math.hypot(dx, dy)
        if L == 0:
            continue
        nx = -dy / L * hw
        ny = dx / L * hw
        left.append(((x1 + nx, y1 + ny), (x2 + nx, y2 + ny)))
        right.append(((x1 - nx, y1 - ny), (x2 - nx, y2 - ny)))
    if not left:
        return []
    polys = []
    # left chain
    lpts = [left[0][0]]
    for i in range(len(left)):
        lpts.append(left[i][1])
        if i + 1 < len(left):
            lpts.append(left[i + 1][0])
    rpts = [right[-1][1]]
    for i in range(len(right) - 1, -1, -1):
        rpts.append(right[i][0])
        if i - 1 >= 0:
            rpts.append(right[i - 1][1])
    poly = lpts + rpts
    if not closed:
        # add caps
        if caps == 'butt':
            pass
        elif caps == 'round':
            # approximate with arcs
            pass
        elif caps == 'square':
            pass
    polys.append(poly)
    return polys
