        x2, y2 = pts[(i + 1) % n]
        a += x1 * y2 - x2 * y1
    return a / 2.0


def ensure_positive(poly):
    if signed_area(poly) < 0:
        return list(reversed(poly))
    return list(poly)


def flatten_quad(p0, p1, p2, steps=16):
    out = []
    for i in range(1, steps + 1):
        u = i / float(steps)
        x = (1 - u) ** 2 * p0[0] + 2 * (1 - u) * u * p1[0] + u * u * p2[0]
        y = (1 - u) ** 2 * p0[1] + 2 * (1 - u) * u * p1[1] + u * u * p2[1]
        out.append((x, y))
    return out


