    for poly in polys:
        flat = _flatten_poly(poly, flatten_steps)
        for pts in flat:
            n = len(pts)
            if n < 3:
                continue
            for i in range(n):
                ax, ay = pts[i]
                bx, by = pts[(i + 1) % n]
                if ay == by:
                    continue
                if ay > by:
                    ax, ay, bx, by = bx, by, ax, ay
                    sign = 1.0
                else:
                    sign = -1.0
                segs.append((ax, ay, bx, by, sign))
    if not segs:
        return cov
    ymin = min(s[1] for s in segs)
    ymax = max(s[3] for s in segs)
    ylo = max(0, int(math.floor(ymin)))
    yhi = min(h - 1, int(math.ceil(ymax)))
