            cur.append((s[3], s[4]))
        elif s[0] == 'Q':
            if not cur:
                cur.append((s[1], s[2]))
            cur.extend(flatten_quad((s[1], s[2]), (s[3], s[4]), (s[5], s[6]), steps))
        else:
            if not cur:
                cur.append((s[1], s[2]))
            cur.append((s[3], s[4]))
    if len(cur) >= 3:
        contours.append(cur)
    return contours


class Canvas:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.buf = bytearray(width * height * 4)

    def clear(self, color):
        b = bytes(color)
        for i in range(self.width * self.height):
            self.buf[i * 4:i * 4 + 4] = b

    def composite(self, cov, color, alpha=1.0):
        w = self.width
        r, g, bl = color
        for i, c in enumerate(cov):
            if c <= 0:
                continue
            a = c * alpha
            if a > 1.0:
                a = 1.0
            o = i * 4
            ia = 1.0 - a
            self.buf[o] = int(round(r * a + self.buf[o] * ia))
            self.buf[o + 1] = int(round(g * a + self.buf[o + 1] * ia))
            self.buf[o + 2] = int(round(bl * a + self.buf[o + 2] * ia))
            self.buf[o + 3] = max(self.buf[o + 3], int(round(255 * a)))

    def fill_paths(self, polys, color, alpha=1.0):
        cov = coverage_of(polys, self.width, self.height)
        self.composite(cov, color, alpha)

    def get(self, x, y):
        o = (y * self.width + x) * 4
        return (self.buf[o], self.buf[o + 1], self.buf[o + 2], self.buf[o + 3])
