"""Shape geometry derived from grid structure."""
import math
from grid import TextGrid

LINEV = set('|:v^<>*o')
LINEH = set('-=<>v^o*')
ARROW = set('v^<>')

def is_line(c):
    return c in '|-=:^v<>/\\*+o'

def is_vline(c):
    return c in '|:'
def is_hline(c):
    return c in '-='
def is_diag(c):
    return c in '/\\'
def is_arrow(c):
    return c in 'v^<>'
def is_marker(c):
    return c == '*'
def is_bullet(c):
    return c == 'o'


class Region:
    def __init__(self, cells, grid):
        self.cells = cells
        self.grid = grid
        xs = [c[0] for c in cells]
        ys = [c[1] for c in cells]
        self.x0, self.y0, self.x1, self.y1 = min(xs), min(ys), max(xs), max(ys)
        self.markers = []
        self.colors = []
        self.text = []
        for (x, y) in cells:
            s = grid.get(x, y)
            self.text.append((x, y, s))


def find_regions(grid):
    """Flood-fill non-line cells -> list of Region."""
    W, H = grid.width, grid.height
    seen = [[False] * (W + 2) for _ in range(H + 2)]
    regions = []
    for y in range(-1, H + 1):
        for x in range(-1, W + 1):
            if seen[y + 1][x + 1]:
                continue
            if x < 0 or y < 0 or x >= W or y >= H or is_line(grid.get(x, y)):
                seen[y + 1][x + 1] = True
                continue
            stack = [(x, y)]
            seen[y + 1][x + 1] = True
            cells = []
            while stack:
                cx, cy = stack.pop()
                cells.append((cx, cy))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = cx + dx, cy + dy
                    if -1 <= nx <= W and -1 <= ny <= H:
                        if not seen[ny + 1][nx + 1]:
                            seen[ny + 1][nx + 1] = True
                            if nx < 0 or ny < 0 or nx >= W or ny >= H or is_line(grid.get(nx, ny)):
                                continue
                            stack.append((nx, ny))
            regions.append(Region(cells, grid))
    return regions


def special_type(region):
    """Look for {xx} markers inside region; return type string or None."""
    import re
    for (x, y, s) in region.text:
        if s == '{' :
            seq = region.grid.get(x + 1, y)
            nxt = region.grid.get(x + 2, y)
            end = region.grid.get(x + 3, y)
            if nxt == '}':
                return seq
            if end == '}':
                return seq + nxt
        if s in ('d', 's', 'o', 'c'):
            # allow single-letter markers preceded by whitespace
            if region.grid.get(x - 1, y) in ' ' and region.grid.get(x + 1, y) == ' ':
                pass
    return None


def color_of(region):
    for (x, y, s) in region.text:
        if s == 'c' and region.grid.get(x - 1, y) in ' |':
            w = ''
            for k in range(1, 6):
                ch = region.grid.get(x + k, y)
                if ch in ' ()':
                    break
                w += ch
            w = w.rstrip()
            if w in COLOR_CODES:
                return ('c' + w, COLOR_CODES[w])
            if w.lower() in DARK_CODES and w.islower():
                return ('c' + w, DARK_CODES[w])
            if w in LIGHT_CODES:
                return ('c' + w, LIGHT_CODES[w])
    return None
