def _offset_polys(path, off):
    """Return polygons of path translated by (off, off) as closed contour polygons."""
    polys = []
    for cont in path:
        pts = []
        for s in cont:
            if not pts:
                pts.append((s[1] + off, s[2] + off))
            pts.append((s[3] + off, s[4] + off))
        if len(pts) >= 3:
            polys.append(ensure_positive(pts))
    return polys


def _closed_polys(path):
    polys = []
    for cont in path:
        pts = []
        for s in cont:
            if not pts:
                pts.append((s[1], s[2]))
            pts.append((s[3], s[4]))
        if len(pts) >= 3:
            polys.append(ensure_positive(pts))
    return polys


