    kx = 0.5522847498
    cx = (x0 + x1) / 2.0
    cy = (y0 + y1) / 2.0
    rx = (x1 - x0) / 2.0
    ry = (y1 - y0) / 2.0
    c1x = rx * kx
    c1y = ry * kx
    segs = []
    segs.append(('C', cx + rx, cy, cx + rx, cy + c1y, cx + c1x, cy + ry, cx, cy + ry))
