def _offset_polys(path, off):
    """Return polygons of path translated by (off, off) as closed contour polygons."""
    polys = []
    for cont in path:
        pts = []
        for s in cont:
            if not pts:
                pts.append((s[1] + off, s[2] + off))
            pts.append((s[3] + off, s[4] + off))
        if len(pts) >= 3:
            polys.append(ensure_positive(pts))
    return polys


def _closed_polys(path):
    polys = []
    for cont in path:
        pts = []
        for s in cont:
            if not pts:
                pts.append((s[1], s[2]))
            pts.append((s[3], s[4]))
        if len(pts) >= 3:
            polys.append(ensure_positive(pts))
    return polys


def _ellipse_path(x0, y0, x1, y1):
    kx = 0.5522847498
    cx = (x0 + x1) / 2.0
    cy = (y0 + y1) / 2.0
    rx = (x1 - x0) / 2.0
    ry = (y1 - y0) / 2.0
    c1x = rx * kx
    c1y = ry * kx
    segs = []
    segs.append(('C', cx + rx, cy, cx + rx, cy + c1y, cx + c1x, cy + ry, cx, cy + ry))
    segs.append(('C', cx, cy + ry, cx - c1x, cy + ry, cx - rx, cy + c1y, cx - rx, cy))
    segs.append(('C', cx - rx, cy, cx - rx, cy - c1y, cx - c1x, cy - ry, cx, cy - ry))
    segs.append(('C', cx, cy - ry, cx + c1x, cy - ry, cx + rx, cy - c1y, cx + rx, cy))
    return segs


def _document_path(x0, y0, x1, y1):
    ch = (y1 - y0) / 2.0
    # top: straight, right side straight, bottom: two quadratic waves
    return [
        ('L', x0, y0, x1, y0),
        ('L', x1, y0, x1, y1),
        ('Q', x1, y1, x1 - (x1 - x0) * 0.75, y1 - ch * 0.5, x0 + (x1 - x0) * 0.5, y1),
        ('Q', x0 + (x1 - x0) * 0.5, y1, x0 + (x1 - x0) * 0.25, y1 + ch * 0.5, x0, y1),
